// Questions in plain English, answered only from what FIELD has seen.
//
// Same rule as the reasoner: no sentence here is generated by a model. A
// question is resolved to one of a handful of intents by pattern, the
// assessment is computed, and the answer is assembled from it - so every
// claim on screen can be traced to the frames that produced it, and a question
// FIELD cannot answer gets "I can't answer that" plus the list of what it can,
// never a confident guess.
//
// That is a product decision, not a limitation to apologise for. A responder
// acting on a fluent, wrong answer in a smoke-filled corridor is the failure
// this whole system exists to avoid. The seam for a local language model is
// resolve(): it may map a sentence to an intent. It may not write the answer.

import { assess, evidenceText, fmtDist } from "./reason.js";
import { kindInfo } from "./ontology.js";

const RESOURCE_WORDS = [
  ["extinguisher", /extinguish/],
  ["first_aid", /first[- ]?aid|med ?kit|bandage|trauma kit/],
  ["aed", /\baed\b|defib/],
  ["fire_alarm", /alarm|pull station/],
  ["fire_hose", /\bhose\b/],
];

const KIND_WORDS = [
  ["fire", /\bfire\b|flame|burning/],
  ["smoke", /smoke/],
  ["water", /water|flood|puddle/],
  ["debris", /debris|rubble/],
  ["stairs", /stair/],
  ["electrical_panel", /panel|fuse|breaker/],
  ["exposed_wires", /wire|wiring|cable/],
  ["broken_glass", /glass/],
  ["gas_cylinder", /gas|cylinder|propane/],
  ["structural_damage", /crack|collapse|ceiling|structur/],
  ["door", /\bdoors?\b/],
  ["window", /window/],
];

export const CAPABILITIES = [
  "Which exit is safest?",
  "What hazards are here?",
  "Is anyone here who needs help?",
  "Where is the nearest fire extinguisher?",
  "What haven't I checked?",
  "Can I use the elevator?",
  "Give me a sitrep.",
];

/** Sentence -> { intent, kind? }. Deterministic, inspectable, cannot invent an intent. */
export function resolve(question) {
  const q = ` ${String(question).toLowerCase().replace(/[’']/g, "'")} `;
  for (const [kind, re] of RESOURCE_WORDS) if (re.test(q)) return { intent: "resource", kind };
  if (/elevator|\blift\b/.test(q)) return { intent: "elevator" };
  if (/haven't|have not|not (yet )?(seen|scanned|checked|looked)|\bmiss(ed|ing)?\b|blind spot|unseen|coverage|where (else )?should i (look|check)|what else/.test(q)) {
    return { intent: "coverage" };
  }
  if (/\bexits?\b|way out|get out|escape|evacuat|\bleave\b|egress|safest (way|route|path)|which way/.test(q)) return { intent: "exit" };
  if (/people|person|anyone|anybody|someone|somebody|victim|casualt|injur|hurt|trapped|\bwho\b|help\b/.test(q)) return { intent: "people" };
  if (/\bwhere\b|\bany\b|is there|are there|see (a|any)/.test(q)) {
    for (const [kind, re] of KIND_WORDS) if (re.test(q)) return { intent: "where", kind };
  }
  if (/hazard|danger|unsafe|\bsafe\b|risk|threat|avoid|careful/.test(q)) return { intent: "hazards" };
  for (const [kind, re] of KIND_WORDS) if (re.test(q)) return { intent: "where", kind };
  if (/summary|sitrep|report|status|overview|what do you see|around me|brief|everything/.test(q)) return { intent: "sitrep" };
  return { intent: "unknown" };
}

const cap = (s) => (s ? s[0].toUpperCase() + s.slice(1) : s);

function where(x) {
  const d = fmtDist(x.distance);
  return d ? `${x.dir}, ${d}` : `${x.dir} (range unknown)`;
}

function line(text, tone = "info", evidence = []) {
  return { text, tone, evidence };
}

function exitSentence(x, recommended) {
  const ev = evidenceText(x);
  if (x.status === "blocked") {
    const extra = x.reasons.slice(1, 3).map((r) => r.text);
    return line(`The ${x.name} is ${x.reasons[0].text}${extra.length ? `; also ${extra.join("; ")}` : ""}.`, "bad", x.evidence);
  }
  if (x.status === "caution") {
    const why = x.reasons.filter((r) => r.severity > 0).map((r) => r.text);
    return line(`The ${x.name} is accessible, but there is ${why.join("; and ")}.`, "warn", x.evidence);
  }
  if (x.status === "unverified") {
    const why =
      x.type === "sign_only"
        ? `I can see an exit sign to the ${x.anchor.dir} but not the door it marks`
        : `seen in one frame only`;
    return line(`The ${x.name} is unconfirmed: ${why}. Look again before relying on it.`, "warn", x.evidence);
  }
  const note = x.type === "door" ? " It is an unmarked door; it may not lead outside." : "";
  const mine = x.reasons.find((r) => r.severity === 0);
  return line(`The ${x.name} appears clear (${mine ? mine.text : ev}).${note}`, "ok", x.evidence);
}

function exitAnswer(a) {
  const lines = [];
  const rec = a.recommendation;
  let headline;
  if (rec.exit) {
    const x = rec.exit;
    const d = fmtDist(x.distance);
    const bearing = a.zone.relative ? "" : `, bearing ${Math.round(x.bearing)}°`;
    headline = `Take the ${x.name}${d ? ` - about ${d}${bearing}` : bearing}.`;
    const others = a.exits.filter((e) => e !== x);
    const order = { blocked: 0, caution: 1, unverified: 2, clear: 3 };
    others.sort((p, q) => order[p.status] - order[q.status]);
    for (const e of others) lines.push(exitSentence(e, false));
    lines.push(exitSentence(x, true));
    if (rec.confidence === "low") lines.push(line("Confidence is low - confirm it with your own eyes before committing.", "warn"));
  } else if (rec.route) {
    const { zone, exit, via, hops } = rec.route;
    headline = "No usable exit seen in this area.";
    for (const e of a.exits) lines.push(exitSentence(e, false));
    const back = via ? `back through the ${via.name} you came in by` : "back the way you came";
    lines.push(
      line(
        `Nearest known way out: the ${exit.name} in ${zone.name}${hops > 1 ? ` (${hops} areas back)` : ""}. Go ${back}. ${exit.status === "clear" ? "It appeared clear" : `Status there: ${exit.status}`} ${exit.ageMin < 1 ? "under a minute ago" : `${Math.round(exit.ageMin)} min ago`}.`,
        exit.status === "clear" ? "ok" : "warn",
        exit.evidence,
      ),
    );
  } else if (a.exits.length) {
    headline = "Every exit I have seen is blocked.";
    for (const e of a.exits) lines.push(exitSentence(e, false));
    lines.push(line("Keep scanning for another way out, and report your position.", "bad"));
  } else {
    headline = "I haven't seen an exit yet.";
    lines.push(line("Pan slowly; exit signs are usually lit and above doors.", "info"));
  }
  for (const c of a.caveats) lines.push(line(c, "warn"));
  for (const d of a.directives.filter((t) => /^Elevator to the/.test(t))) lines.push(line(d, "bad"));
  return { headline, lines };
}

function hazardAnswer(a) {
  const lines = [];
  const crit = a.compounds.filter((c) => c.a.info.category !== "person");
  for (const c of crit) lines.push(line(`${cap(c.text)}.${c.advice && !c.unsure ? ` ${c.advice}` : ""}`, c.severity >= 3 ? "bad" : "warn", c.evidence));
  for (const h of a.hazards) {
    lines.push(line(`${cap(h.name)}: ${where(h)} - ${evidenceText(h)}.`, h.level === "glimpsed" ? "info" : h.info.severity >= 3 ? "bad" : "warn", [h.id]));
  }
  const n = a.hazards.filter((h) => h.level !== "glimpsed").length;
  const g = a.hazards.length - n;
  const parts = [`${n} hazard${n === 1 ? "" : "s"} seen more than once`];
  if (crit.length) parts.push(`${crit.length} dangerous combination${crit.length === 1 ? "" : "s"}`);
  if (g) parts.push(`${g} glimpsed once - look again`);
  const headline = a.hazards.length ? `${cap(parts.join(", "))}.` : "No hazards seen so far.";
  if (a.coverage.scannedDeg < 360) lines.push(line(a.coverage.text, "warn"));
  return { headline, lines };
}

function peopleAnswer(a) {
  const p = a.people;
  const lines = [];
  if (!p.all.length) {
    return { headline: "No people seen in this area.", lines: a.coverage.scannedDeg < 360 ? [line(a.coverage.text, "warn")] : [] };
  }
  const n = Math.max(p.likely, p.atLeast);
  const headline = `${n} ${n === 1 ? "person" : "people"} seen here${p.needsHelp.length ? `; ${p.needsHelp.length} may need help` : ""}.`;
  for (const x of p.needsHelp) lines.push(line(`${cap(x.name)} to the ${where(x)}: ${x.reasons.join("; ")}.`, "bad", [x.id]));
  for (const x of p.all.filter((y) => !p.needsHelp.includes(y) && !p.needsHelp.some((n) => n.id === y.id))) {
    lines.push(line(`${cap(x.name)} to the ${where(x)}${x.e.attrs.status === "ok" ? " - you marked them OK" : ""}.`, "info", [x.id]));
  }
  if (n > p.atLeast) lines.push(line(`Counted as separate sightings; someone who moved between views may be counted twice. At least ${p.atLeast} ${p.atLeast === 1 ? "was" : "were"} in view at once.`, "info"));
  lines.push(line("FIELD flags people who may need help. It does not assess injuries.", "info"));
  return { headline, lines };
}

function resourceAnswer(a, model, kind, now) {
  const name = kindInfo(kind).name;
  const here = a.resources.filter((r) => r.kind === kind);
  if (here.length) {
    const r = here[0];
    return {
      headline: `${cap(name)} to the ${where(r)}.`,
      lines: [line(`${cap(evidenceText(r))}${here.length > 1 ? `; ${here.length - 1} more in this area` : ""}.`, "ok", [r.id])],
    };
  }
  for (const z of [...model.zones].reverse()) {
    if (z.id === a.zone?.id) continue;
    const other = assess(model, { now, zoneId: z.id, followRoute: false }).resources.find((r) => r.kind === kind);
    if (other) return { headline: `No ${name} here. There is one in ${z.name}, to the ${where(other)} from where you stood.`, lines: [line(evidenceText(other), "info", [other.id])] };
  }
  return { headline: `No ${name} seen yet.`, lines: a.coverage.scannedDeg < 360 ? [line(a.coverage.text, "warn")] : [] };
}

function whereAnswer(a, kind) {
  const name = kindInfo(kind).name;
  const items = a.zone ? [...a.hazards, ...a.resources, ...a.people.all, ...a.exits.flatMap((x) => x.members)].filter((x) => x.kind === kind) : [];
  const uniq = [...new Map(items.map((x) => [x.id, x])).values()];
  if (!uniq.length) return { headline: `No ${name} seen in this area.`, lines: a.coverage.scannedDeg < 360 ? [line(a.coverage.text, "warn")] : [] };
  return {
    headline: `${uniq.length === 1 ? cap(name) : `${uniq.length} × ${name}`}: ${uniq.map((x) => x.dir).join(", ")}.`,
    lines: uniq.map((x) => line(`${cap(name)} to the ${where(x)} - ${evidenceText(x)}.`, "info", [x.id])),
  };
}

function coverageAnswer(a) {
  const c = a.coverage;
  if (!c.unseen.length) return { headline: c.text, lines: [] };
  const big = c.unseen[0];
  return {
    headline: `Look ${a.zone.relative ? "" : "to the "}${big.name} next.`,
    lines: [line(c.text, "warn"), line("Anything there is invisible to FIELD - including exits, hazards and people.", "info")],
  };
}

function elevatorAnswer(a) {
  const seen = a.elevators;
  const avoid = a.directives.find((d) => /elevator/i.test(d));
  if (avoid) return { headline: "Do not use the elevator.", lines: [line(avoid, "bad", seen.map((x) => x.id))] };
  return {
    headline: seen.length ? "Nothing here rules the elevator out, but stairs are safer in any emergency." : "No elevator seen in this area.",
    lines: seen.map((x) => line(`Elevator to the ${where(x)}.`, "info", [x.id])),
  };
}

function sitrepAnswer(a) {
  const lines = [];
  const rec = a.recommendation;
  if (rec.exit) lines.push(line(`Way out: ${rec.exit.name}, ${rec.exit.status}${fmtDist(rec.exit.distance) ? `, ${fmtDist(rec.exit.distance)}` : ""}.`, rec.exit.status === "clear" ? "ok" : "warn", rec.evidence));
  else lines.push(line("No usable exit identified in this area.", "bad"));
  const blocked = a.exits.filter((x) => x.status === "blocked");
  if (blocked.length) lines.push(line(`Blocked: ${blocked.map((x) => x.name).join(", ")}.`, "bad", blocked.flatMap((x) => x.evidence)));
  for (const c of a.compounds.filter((c) => !c.unsure && c.severity >= 3)) lines.push(line(cap(c.text) + ".", "bad", c.evidence));
  const hz = a.hazards.filter((h) => h.level !== "glimpsed");
  if (hz.length) lines.push(line(`Hazards: ${hz.map((h) => `${h.name} (${h.dir})`).join(", ")}.`, "warn", hz.map((h) => h.id)));
  lines.push(line(`People: ${Math.max(a.people.likely, a.people.atLeast)}${a.people.needsHelp.length ? `, ${a.people.needsHelp.length} may need help` : ""}.`, a.people.needsHelp.length ? "bad" : "info", a.people.needsHelp.map((p) => p.id)));
  if (a.resources.length) lines.push(line(`Resources: ${a.resources.map((r) => `${r.name} (${r.dir})`).join(", ")}.`, "info", a.resources.map((r) => r.id)));
  lines.push(line(a.coverage.text, a.coverage.scannedDeg < 360 ? "warn" : "info"));
  for (const d of a.directives) lines.push(line(d, "info"));
  return { headline: `${a.incident} - ${a.zone?.name ?? "no area"}.`, lines };
}

/**
 * Answer a question about the current area.
 * Returns { intent, headline, lines: [{ text, tone, evidence }], evidence, speech }.
 */
export function answer(model, question, { now = Date.now() } = {}) {
  const r = resolve(question);
  const a = assess(model, { now });
  let out;
  if (!a.zone && r.intent !== "unknown") {
    out = { headline: "Nothing scanned yet.", lines: [line("Point the camera around the space, slowly, all the way round.", "info")] };
  } else {
    switch (r.intent) {
      case "exit":
        out = exitAnswer(a);
        break;
      case "hazards":
        out = hazardAnswer(a);
        break;
      case "people":
        out = peopleAnswer(a);
        break;
      case "resource":
        out = resourceAnswer(a, model, r.kind, now);
        break;
      case "where":
        out = whereAnswer(a, r.kind);
        break;
      case "coverage":
        out = coverageAnswer(a);
        break;
      case "elevator":
        out = elevatorAnswer(a);
        break;
      case "sitrep":
        out = sitrepAnswer(a);
        break;
      default:
        out = {
          headline: "I can't answer that from what I've seen.",
          lines: [line(`I can answer: ${CAPABILITIES.join(" · ")}`, "info")],
        };
    }
  }
  const evidence = [...new Set(out.lines.flatMap((l) => l.evidence))];
  const speech = [out.headline, ...out.lines.slice(0, 3).map((l) => l.text)].join(" ");
  return { intent: r.intent, kind: r.kind, ...out, evidence, speech, assessment: a };
}

/** Plain-text handoff for incident command: every area, timestamped, nothing invented. */
export function handoff(model, { now = Date.now() } = {}) {
  const out = [`FIELD situation report - ${new Date(now).toISOString()}`, `Incident: ${assess(model, { now }).incident}`, ""];
  for (const z of model.zones) {
    const a = assess(model, { now, zoneId: z.id, followRoute: false });
    out.push(`## ${z.name}`);
    for (const l of sitrepAnswer(a).lines) out.push(`- ${l.text}`);
    out.push("");
  }
  out.push("Generated on-device. Positions are bearings from where the responder stood; ranges are estimates from object size or floor geometry.");
  return out.join("\n");
}
